CREATE OR REPLACE FUNCTION public.insight_summary(_tz text, _start date, _end date)
RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $fn$
WITH fs AS (SELECT *, (started_at AT TIME ZONE _tz)::date AS d, extract(hour FROM started_at AT TIME ZONE _tz)::int AS h FROM public.focus_sessions WHERE user_id=auth.uid() AND (started_at AT TIME ZONE _tz)::date BETWEEN _start AND _end), er AS (SELECT * FROM public.energy_ratings WHERE user_id=auth.uid() AND local_date BETWEEN _start AND _end), i AS (SELECT *,extract(hour FROM at AT TIME ZONE _tz)::int AS h FROM public.interruptions WHERE user_id=auth.uid() AND (at AT TIME ZONE _tz)::date BETWEEN _start AND _end), hours AS (SELECT h AS hour,sum(actual_min) AS minutes,count(*) AS count,count(energy_after) AS energy_n,round(avg(energy_after)::numeric,2) AS avg_energy FROM fs GROUP BY h), best AS (SELECT * FROM hours WHERE count>=3 AND energy_n>=3 ORDER BY avg_energy DESC,minutes DESC,hour LIMIT 1), p AS (SELECT count(*) FILTER(WHERE primed) AS primed_n,count(*) FILTER(WHERE NOT primed) AS unprimed_n,round((avg(rating) FILTER(WHERE primed))::numeric,2) AS primed_avg,round((avg(rating) FILTER(WHERE NOT primed))::numeric,2) AS unprimed_avg FROM er WHERE kind='after_meeting'), itop AS (SELECT reason,CASE WHEN reason='custom' THEN custom_label END AS label,count(*) AS count,count(*) FILTER(WHERE source='self') AS self FROM i GROUP BY 1,2 ORDER BY count(*) DESC,reason LIMIT 1), days AS (SELECT generate_series(_start::timestamp,_end::timestamp,interval '1 day')::date AS d), energy AS (SELECT h,energy_before AS b,energy_after AS a FROM fs WHERE energy_before IS NOT NULL AND energy_after IS NOT NULL), buckets AS (SELECT CASE WHEN planned_min<=25 THEN '≤25' WHEN planned_min<=50 THEN '26–50' WHEN planned_min<=90 THEN '51–90' ELSE '90+' END AS bucket,CASE WHEN planned_min<=25 THEN 1 WHEN planned_min<=50 THEN 2 WHEN planned_min<=90 THEN 3 ELSE 4 END AS ord,planned_min,actual_min FROM fs)
SELECT jsonb_build_object(
'start',_start,'end',_end,'session_count',(SELECT count(*) FROM fs),'rating_count',(SELECT count(*) FROM er)+(SELECT count(*) FROM fs WHERE energy_before IS NOT NULL OR energy_after IS NOT NULL),
'by_hour',coalesce((SELECT jsonb_agg(to_jsonb(hours) ORDER BY hour) FROM hours),'[]'::jsonb),
'by_day',(SELECT jsonb_agg(jsonb_build_object('day',days.d,'minutes',coalesce(f.minutes,0)) ORDER BY days.d) FROM days LEFT JOIN (SELECT d,sum(actual_min) AS minutes FROM fs GROUP BY d) f USING(d)),
'by_week',(SELECT jsonb_agg(to_jsonb(w) ORDER BY week) FROM (SELECT date_trunc('week',days.d)::date AS week,sum(coalesce(f.minutes,0)) AS minutes FROM days LEFT JOIN (SELECT d,sum(actual_min) AS minutes FROM fs GROUP BY d) f USING(d) GROUP BY 1) w),
'energy_by_hour',coalesce((SELECT jsonb_agg(to_jsonb(q) ORDER BY hour) FROM (SELECT h AS hour,round(avg(v)::numeric,2) AS avg FROM (SELECT extract(hour FROM at AT TIME ZONE _tz)::int AS h,rating AS v FROM er UNION ALL SELECT h,energy_before FROM fs WHERE energy_before IS NOT NULL UNION ALL SELECT extract(hour FROM ended_at AT TIME ZONE _tz)::int,energy_after FROM fs WHERE energy_after IS NOT NULL) e GROUP BY h) q),'[]'::jsonb),
'primed',(SELECT to_jsonb(p) FROM p),'intent_outcomes',(SELECT jsonb_build_object('yes',count(*) FILTER(WHERE intent_outcome='yes'),'partly',count(*) FILTER(WHERE intent_outcome='partly'),'no',count(*) FILTER(WHERE intent_outcome='no')) FROM er WHERE kind='after_meeting' AND primed),
'interruptions',coalesce((SELECT jsonb_agg(to_jsonb(q)) FROM (SELECT coalesce(source,'unknown') AS source,reason,CASE WHEN reason='custom' THEN custom_label END AS label,count(*) AS count FROM i GROUP BY 1,2,3) q),'[]'::jsonb),
'interruptions_by_hour',(SELECT jsonb_agg(jsonb_build_object('hour',g.h,'self',coalesce(x.self,0),'external',coalesce(x.external,0),'unknown',coalesce(x.unknown,0)) ORDER BY g.h) FROM generate_series(0,23) g(h) LEFT JOIN (SELECT h,count(*) FILTER(WHERE source='self') AS self,count(*) FILTER(WHERE source='external') AS external,count(*) FILTER(WHERE source IS NULL) AS unknown FROM i GROUP BY h) x USING(h)),
'completion',(SELECT jsonb_build_object('planned',coalesce(sum(planned_min),0),'actual',coalesce(sum(actual_min),0),'rate',round(100.0*sum(actual_min)/nullif(sum(planned_min),0),1)) FROM fs),
'completion_buckets',coalesce((SELECT jsonb_agg(to_jsonb(q) ORDER BY ord) FROM (SELECT bucket,ord,count(*) AS count,round(100.0*sum(actual_min)/nullif(sum(planned_min),0),1) AS rate FROM buckets GROUP BY bucket,ord) q),'[]'::jsonb),
'focus_energy',(SELECT jsonb_build_object('count',count(*),'before',round(avg(b)::numeric,2),'after',round(avg(a)::numeric,2),'change',round(avg(a-b)::numeric,2)) FROM energy),
'energy_change_by_hour',coalesce((SELECT jsonb_agg(to_jsonb(q) ORDER BY hour) FROM (SELECT h AS hour,count(*) AS count,round(avg(a-b)::numeric,2) AS change FROM energy GROUP BY h) q),'[]'::jsonb),
'findings',jsonb_build_object('best',(SELECT to_jsonb(best) FROM best),'primed',(SELECT CASE WHEN primed_n>=3 AND unprimed_n>=3 THEN jsonb_build_object('difference',primed_avg-unprimed_avg,'primed_n',primed_n,'unprimed_n',unprimed_n) ELSE NULL END FROM p),'interruption',(SELECT CASE WHEN count>=3 THEN to_jsonb(itop) ELSE NULL END FROM itop))
) $fn$;
GRANT EXECUTE ON FUNCTION public.insight_summary(text,date,date) TO authenticated;
REVOKE EXECUTE ON FUNCTION public.insight_summary(text,date,date) FROM PUBLIC,anon;
CREATE OR REPLACE FUNCTION public.get_insights(_tz text,_period text)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public AS $fn$
DECLARE today date := (now() AT TIME ZONE _tz)::date; first_day date; monday date := date_trunc('week',now() AT TIME ZONE _tz)::date;
BEGIN
IF _period NOT IN ('7','30','all') THEN RAISE EXCEPTION 'Invalid insights period'; END IF;
IF _period='all' THEN SELECT least(coalesce((SELECT min((started_at AT TIME ZONE _tz)::date) FROM public.focus_sessions WHERE user_id=auth.uid()),today),coalesce((SELECT min(local_date) FROM public.energy_ratings WHERE user_id=auth.uid()),today),coalesce((SELECT min((at AT TIME ZONE _tz)::date) FROM public.interruptions WHERE user_id=auth.uid()),today)) INTO first_day; ELSE first_day := today-(_period::int-1); END IF;
RETURN public.insight_summary(_tz,first_day,today)||jsonb_build_object('period',_period,'last_week',public.insight_summary(_tz,monday-7,monday-1),'previous_week',public.insight_summary(_tz,monday-14,monday-8),'trend_start',monday-84);
END $fn$;
GRANT EXECUTE ON FUNCTION public.get_insights(text,text) TO authenticated;
REVOKE EXECUTE ON FUNCTION public.get_insights(text,text) FROM PUBLIC,anon;